  have q := fun k => IsLocalization.AtPrime.equivQuotMaximalIdealPow p S k;
  (Ideal.Quotient.factorₐ R ⋯).comp ↑(q n) = (↑(q m)).comp (Ideal.Quotient.factorₐ R ⋯)

LinearStudy.primePowerQuotientEquiv_symm_naturality.{u_1} {R : Type u_1} [CommRing R] (p : Ideal R) [p.IsMaximal]
