    let Q := C ⧸ Ideal.map (algebraMap R C) J;
    Submodule.annihilator (nilradical Q) =
      Ideal.span {(Ideal.Quotient.mk (Ideal.map (algebraMap R C) J)) ((algebraMap R C) theta)}) :
  Submodule.annihilator (nilradical (R ⧸ J)) = Ideal.span {(Ideal.Quotient.mk J) theta}

LinearStudy.coefficientDeterminant_annihilates_quotient.{u_1, u_2} {R : Type u_1} [CommRing R] {ι : Type u_2}
