LinearStudy.homogeneous_projective_chart_pullback_ideal.{u_1} {K : Type u_1} [Field K] {n : ℕ}
  (I : Ideal (MvPolynomial (Fin (n + 1)) K))
  (hI : Ideal.IsHomogeneous (MvPolynomial.homogeneousSubmodule (Fin (n + 1)) K) I)
  (F : Fin (n + 1) → MvPolynomial (Fin (n + 1)) K) :
  have D := LinearStudy.affineChartPolynomialMap;
  have p0 := D (F 0);
  have p := fun i => D (F i.succ);
  Ideal.map (LinearStudy.rationalPolynomialChartMap p0 p).toRingHom (Ideal.map D.toRingHom I) =
    Ideal.map ((algebraMap (MvPolynomial (Fin n) K) (Localization.Away p0)).comp D.toRingHom)
      (Ideal.map (MvPolynomial.aeval F).toRingHom I)

