  (LinearStudy.awayQuotientEquiv V.affineIdeal p0).toRingEquiv.toRingHom.comp
      ((Ideal.Quotient.mk J).comp (LinearStudy.rationalPolynomialChartMap p0 p).toRingHom) =
    (LinearStudy.projectiveChartOpenPolynomialMap f V).toRingHom

LinearStudy.projectiveChartOpenMap_ambient_quotient_comp {n : ℕ} (f : LinearStudy.HomogeneousEndomorphism n)
  (V : LinearStudy.IntegralProjectiveEquations n) (hq : 0 < f.degree) (hf : Function.Surjective f.onPoints)
  (hV : f.onPoints ⁻¹' V.zeroSet = V.zeroSet) (x : Fin n → ℂ)
