LinearStudy.polynomial_quotient_coordinate_actual_zero.{u_1, u_2, u_3} {K : Type u_1} {σ : Type u_2} {τ : Type u_3}
  [Field K] (E : MvPolynomial σ K ≃ₐ[K] MvPolynomial τ K) (I : Ideal (MvPolynomial σ K)) (J : Ideal (MvPolynomial τ K))
  (hJ : J = Ideal.map E.toRingEquiv.toRingHom I) (q : MvPolynomial τ K ⧸ J →ₐ[K] K) :
