Ideal.depth_eq_sSup_length_isRegular.{v, u} {R : Type u} [CommRing R] [Small R] [IsNoetherianRing R] (I : Ideal R)
  (M : ModuleCat R) [Module.Finite R ↑M] (smul_lt : I • ⊤ < ⊤) :
  I.depth M = sSup {x | ∃ rs, ∃ (_ : RingTheory.Sequence.IsRegular (↑M) rs) (_ : ∀ r ∈ rs, r ∈ I), ↑rs.length = x}

IsLocalRing.ideal_depth_eq_sSup_length_isRegular.{v, u} {R : Type u} [CommRing R] [Small R] [IsLocalRing R]
  [IsNoetherianRing R] (I : Ideal R) (netop : I ≠ ⊤) (M : ModuleCat R) [Module.Finite R ↑M] [Nontrivial ↑M] :
  I.depth M = sSup {x | ∃ rs, ∃ (_ : RingTheory.Sequence.IsRegular (↑M) rs) (_ : ∀ r ∈ rs, r ∈ I), ↑rs.length = x}

